// One output item per attachment.
// Emails without attachments produce no items, so the run simply ends.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const binary = item.binary || {};
  const keys = Object.keys(binary);
  if (!keys.length) continue;

  let sender = 'unknown-sender';
  if (typeof j.from === 'string' && j.from) sender = j.from;
  else if (j.from && Array.isArray(j.from.value) && j.from.value[0] && j.from.value[0].address) sender = j.from.value[0].address;
  else if (j.from && j.from.text) sender = j.from.text;

  const messageId = j.id || j.messageId || '';
  const subject = j.subject || '(no subject)';
  const receivedAt = j.date || j.internalDate || '';

  keys.forEach((key, idx) => {
    const bin = binary[key] || {};
    out.push({
      json: {
        message_id: String(messageId),
        sender: String(sender),
        subject: String(subject),
        received_at: String(receivedAt),
        file_name: bin.fileName || `attachment-${idx + 1}`,
        mime_type: bin.mimeType || 'application/octet-stream',
      },
      binary: { data: bin },
    });
  });
}
return out;

// Compare every extracted attachment against the Attachment Log.
// An attachment counts as saved only when BOTH the message ID and the
// file name already appear in the log.
const attachments = $('2. Extract Attachments').all();
const rows = $input.all().map(r => r.json || {});
return attachments.map((att, i) => {
  const a = att.json || {};
  const dupe = rows.some(r =>
    String(r.message_id || '') === String(a.message_id || '') &&
    String(r.file_name || '') === String(a.file_name || '')
  );
  return { json: { ...a, already_saved: dupe }, binary: att.binary, pairedItem: { item: i } };
});

// Build a Drive-safe, unique file name: 2026-01-31_sender_original-name.pdf
// The date prefix keeps files sorted and stops same-name overwrites.
function slug(s) {
  return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'file';
}
return $input.all().map((item, i) => {
  const a = item.json || {};
  const d = new Date(a.received_at || Date.now());
  const datePart = isNaN(d) ? 'undated' : d.toISOString().slice(0, 10);
  const senderPart = slug(String(a.sender || '').split('@')[0]);
  const safeName = String(a.file_name || 'attachment').replace(/[\\/:*?"<>|]/g, '-').trim();
  return {
    json: { ...a, drive_file_name: `${datePart}_${senderPart}_${safeName}` },
    binary: item.binary,
    pairedItem: { item: i },
  };
});

// Merge the Drive upload result with the email metadata into one log row.
const meta = $('6. Rename File').all();
return $input.all().map((item, i) => {
  const m = (meta[i] && meta[i].json) || {};
  const drive = item.json || {};
  return {
    json: {
      saved_at: new Date().toISOString(),
      file_name: m.file_name || '',
      drive_file_name: m.drive_file_name || drive.name || '',
      sender: m.sender || '',
      subject: m.subject || '',
      message_id: m.message_id || '',
      drive_link: drive.webViewLink || '',
      drive_id: drive.id || '',
    },
  };
});
